package dz.cardiag.app.core

import kotlinx.serialization.Serializable

/** Canonical product flow: Vehicle -> OBD -> Scan -> DTC/Live Data -> Diagnosis -> Report -> History. */
@Serializable
data class VehicleRecord(
    val id: String,
    val make: String,
    val model: String,
    val year: Int? = null,
    val engine: String? = null,
