@Composable
fun SymptomDiagnosisScreen(
    padding: PaddingValues,
    arabic: Boolean,
    hasVehicle: Boolean,
    onBack: () -> Unit,
    onOpenAi: () -> Unit
) {
    val scope = rememberCoroutineScope()
    var complaint by remember { mutableStateOf("") }
    var whenHappens by remember { mutableStateOf("") }
    var engineState by remember { mutableStateOf("") }
    var category by remember { mutableStateOf(SymptomCategory.OTHER) }
    var severity by remember { mutableStateOf(SymptomSeverity.MODERATE) }
    var loading by remember { mutableStateOf(false) }
    var summary by remember { mutableStateOf<String?>(null) }
    var error by remember { mutableStateOf<String?>(null) }
    val context = LocalContext.current

    LazyColumn(
        modifier = Modifier.fillMaxSize().padding(padding),
        contentPadding = PaddingValues(bottom = 24.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        item { CarDiagTopBar(stringResource(R.string.symptom_title), stringResource(R.string.symptom_subtitle), onBack = onBack) }
        if (!hasVehicle) {
            item { CarDiagInfoCard(stringResource(R.string.symptom_title), stringResource(R.string.symptom_no_vehicle)) }
        }
        item {
            Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(stringResource(R.string.symptom_category_label), style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                SymptomCategoryChipRow(category) { category = it }
            }
        }
        item {
            Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                OutlinedTextField(
                    value = complaint, onValueChange = { complaint = it; error = null },
                    modifier = Modifier.fillMaxWidth(),
                    minLines = 3,
                    label = { Text(stringResource(R.string.symptom_complaint_label)) },
                    placeholder = { Text(stringResource(R.string.symptom_complaint_placeholder)) }
                )
                OutlinedTextField(
                    value = whenHappens, onValueChange = { whenHappens = it },
                    modifier = Modifier.fillMaxWidth(),
                    minLines = 2,
                    label = { Text(stringResource(R.string.symptom_when_label)) },
                    placeholder = { Text(stringResource(R.string.symptom_when_placeholder)) }
                )
                OutlinedTextField(
                    value = engineState, onValueChange = { engineState = it },
                    modifier = Modifier.fillMaxWidth(),
                    minLines = 2,
                    label = { Text(stringResource(R.string.symptom_engine_label)) },
                    placeholder = { Text(stringResource(R.string.symptom_engine_placeholder)) }
                )
            }
        }
        item {
            Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(stringResource(R.string.symptom_severity_label), style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    SymptomSeverityChip(stringResource(R.string.symptom_severity_mild), SymptomSeverity.MILD == severity) { severity = SymptomSeverity.MILD }
                    SymptomSeverityChip(stringResource(R.string.symptom_severity_moderate), SymptomSeverity.MODERATE == severity) { severity = SymptomSeverity.MODERATE }
                    SymptomSeverityChip(stringResource(R.string.symptom_severity_severe), SymptomSeverity.SEVERE == severity) { severity = SymptomSeverity.SEVERE }
                }
            }
        }
        item {
            Button(
                onClick = {
                    scope.launch {
                        loading = true
                        error = null
                        runCatching {
                            DiagnosticService().runDiagnostic(
                                vehicleModelId = null,
                                userVehicleId = null,
                                complaint = complaint.trim(),
                                language = if (arabic) "ar" else "fr",
                                symptoms = buildJsonObject {
                                    put("source", "symptom_only")
                                    put("category", category.name)
                                    put("severity", severity.name)
                                    put("when_happens", whenHappens)
                                    put("engine_state", engineState)
                                }
                            )
                        }
                            .onSuccess { response ->
                                val diag = response["diagnosis"]?.toString().orEmpty()
                                summary = if (diag.isBlank()) context.getString(R.string.ai_no_evidence) else diag
                            }
                            .onFailure { error = it.message ?: context.getString(R.string.ai_unavailable, context.getString(R.string.ai_unavailable, "")) }
                        loading = false
                    }
                },
                enabled = !loading && complaint.isNotBlank() && hasVehicle,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp)
            ) { Text(stringResource(R.string.symptom_analyze)) }
        }
        if (loading) item { CarDiagLoadingState(stringResource(R.string.symptom_analyzing)) }
        summary?.let { item { CarDiagInfoCard(stringResource(R.string.ai_summary), it) } }
        error?.let { item { CarDiagInfoCard(stringResource(R.string.state_error), it) } }
        item {
            OutlinedButton(
                onClick = onOpenAi,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp)
            ) { Text(stringResource(R.string.home_ai_assistant)) }
        }
    }
}

private enum class SymptomCategory(val labelRes: Int) {
    ENGINE(R.string.symptom_other),
    ELECTRICAL(R.string.symptom_other),
    BRAKES(R.string.symptom_other),
    AIRBAG(R.string.symptom_other),
    TRANSMISSION(R.string.symptom_other),
    COOLING(R.string.symptom_other),
    EMISSIONS(R.string.symptom_other),
    OTHER(R.string.symptom_other),
}

private enum class SymptomSeverity { MILD, MODERATE, SEVERE }

@Composable
private fun SymptomCategoryChipRow(current: SymptomCategory, onSelect: (SymptomCategory) -> Unit) {
    val categories = listOf(
        SymptomCategory.ENGINE to "Engine",
        SymptomCategory.ELECTRICAL to "Electrical",
        SymptomCategory.BRAKES to "Brakes",
        SymptomCategory.AIRBAG to "Airbag",
        SymptomCategory.TRANSMISSION to "Transmission",
        SymptomCategory.COOLING to "Cooling",
        SymptomCategory.EMISSIONS to "DPF/EGR",
        SymptomCategory.OTHER to "Other"
    )
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        categories.chunked(3).forEach { row ->
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                row.forEach { (cat, label) ->
                    AssistChip(
                        onClick = { onSelect(cat) },
                        label = { Text(label) },
                        colors = if (cat == current) AssistChipDefaults.assistChipColors(containerColor = MaterialTheme.colorScheme.primaryContainer) else AssistChipDefaults.assistChipColors()
                    )
                }
            }
        }
    }
}

@Composable
private fun SymptomSeverityChip(label: String, selected: Boolean, onClick: () -> Unit) {
    AssistChip(
        onClick = onClick,
        label = { Text(label) },
        colors = if (selected) AssistChipDefaults.assistChipColors(containerColor = MaterialTheme.colorScheme.primaryContainer) else AssistChipDefaults.assistChipColors()
    )
}

